```javascript
const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

rl.on('line', (input) => {
    const [a, b] = input.split(' ').map(Number);
    const diffDays = Math.min(a, b);
    const remaining = Math.abs(a - b);
    const sameDays = Math.floor(remaining / 2);
    console.log(`${diffDays} ${sameDays}`);
    rl.close();
});
```

