    input: process.stdin,
    output: process.stdout
});

readline.on('line', (line) => {
    const [a, b] = line.split(' ').map(Number);
    const daysDifferent = Math.min(a, b);
    const remainingA = a - daysDifferent;
    const remainingB = b - daysDifferent;
    const daysSame = Math.floor((remainingA + remainingB) / 2);
    console.log(`${daysDifferent} ${daysSame}`);
    readline.close();
});
